sections.body:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"    # depuis le Registry
      version = "~> 5.0"           # contrainte de version
    }
  }
}

# Configurer le provider (région, authentification via l'environnement)
provider "aws" {
  region = "eu-west-3"
  # les credentials viennent des variables d'env / du profil, PAS du code
}

# Dans le module : déclarer les alias attendus
terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      configuration_aliases = [aws.primary, aws.secondary]
    }
  }
}

# Chez l'appelant : fournir les instances de provider
module "replication" {
  source = "./modules/replication"
  providers = {
    aws.primary   = aws.europe
    aws.secondary = aws.usa
  }
}
